export function overlaps(
  /** @type {Session} */ a,
  /** @type {Session} */ b,
) {
  return a.start < b.end && b.start < a.end;
}

/**
 * Every pair of the given sessions that overlap, ordered by the earlier
 * session's start and then the later's, each pair earlier first.
 */
export function clashes(/** @type {Session[]} */ sessions) {
  const sorted = [...sessions].sort((a, b) =>
    a.start.localeCompare(b.start) || a.end.localeCompare(b.end) ||
    a.id.localeCompare(b.id)
  );
  /** @type {[Session, Session][]} */
  const pairs = [];
  for (let i = 0; i < sorted.length; i++) {
    for (let j = i + 1; j < sorted.length; j++) {
      if (sorted[j].start >= sorted[i].end) break;
      pairs.push([sorted[i], sorted[j]]);
    }
  }
  return pairs;
}

